#include "th10/game/player_pickup_sweep.hpp"
#include <cmath>
#include <cstdio>
#include <cstring>
static int fails;
#define CHECK(x) do {if(!(x)){std::printf("FAIL %d: %s\n",__LINE__,#x);++fails;}}while(0)
static int score, player_value, interval_value, stop_count, retire_count, create_count, write_value, flags_value, indicator_count;
static int saved_field=77, new_handle=900; static short indicator_value; static int indicator_style, indicator_parts; static float indicator_size, indicator_speed; static int filter_value;
static int Filter(void*,void*,const float*){return filter_value;}
static int PlayerHit(){return player_value;} static int Interval(Pickup*,int n){CHECK(n==4);return interval_value;}
static void Stop(Pickup*,PickupDescriptor*){++stop_count;} static int Read(int){return saved_field;}
static void Retire(Pickup*){++retire_count;} static int Create(void*,int script,int layer){CHECK(script==12);CHECK(layer==15);++create_count;return new_handle;}
static void Write(int h,int v){CHECK(h==new_handle);write_value=v;} static void Flags(int h,unsigned f){CHECK(h==new_handle);flags_value=(int)f;}
static void Indicator(short v,PickupManager*,const float*,float size,float speed,int style,int parts){++indicator_count;indicator_value=v;indicator_size=size;indicator_speed=speed;indicator_style=style;indicator_parts=parts;}
static PickupSweepEnv Env(){PickupSweepEnv e={};e.score=&score;e.player_hit_test=PlayerHit;e.interval_test=Interval;e.stop_animation=Stop;e.read_animation_field=Read;e.retire_animation=Retire;e.create_animation=Create;e.write_animation_field=Write;e.or_animation_flags=Flags;e.spawn_indicator=Indicator;return e;}
static void Reset(PickupManager& m){std::memset(&m,0,sizeof(m));m.generation_end=1;score=100;player_value=interval_value=stop_count=retire_count=create_count=write_value=flags_value=indicator_count=filter_value=0;}
static void SetupPickup(PickupManager& m,PickupDescriptor& d,int type){std::memset(&d,0,sizeof(d));d.value=30;d.width=20;d.height=20;d.type=(unsigned char)type;d.collected_script=7;d.filter=Filter;Pickup& p=m.pickups[0];p.state=1;p.animation_handle=123;p.position[0]=5;p.position[1]=10;p.velocity_scale=8;p.descriptor=&d;}
static void TestEarly(){PickupManager m={};int out=55;float p[2]={0,0},s[2]={10,10};PickupSweepEnv e=Env();CHECK(Player_CollectAndScoreFields(&out,&m,p,s,&e)==0);CHECK(out==55);}
static void TestOrdinaryPickup(){PickupManager m;Reset(m);PickupDescriptor d;SetupPickup(m,d,2);float p[2]={0,0},s[2]={10,10};int out=8;PickupSweepEnv e=Env();CHECK(Player_CollectAndScoreFields(&out,&m,p,s,&e)==30);CHECK(out==0);Pickup& q=m.pickups[0];CHECK(q.collected==1&&q.initialized==1&&q.state==2);CHECK(stop_count==1&&retire_count==1&&create_count==1);CHECK(q.animation_handle==900&&write_value==77&&flags_value==4);CHECK(std::fabs(q.transition_scale-.1f)<1e-6f&&std::fabs(q.velocity_scale-1.0f)<1e-6f);CHECK(indicator_count==1&&indicator_value==30&&indicator_style==13&&indicator_parts==10);CHECK(indicator_size==32.0f&&std::fabs(indicator_speed-1.4f)<1e-6f);CHECK(score==101);}
static void TestFilterAndBounds(){PickupManager m;Reset(m);PickupDescriptor d;SetupPickup(m,d,1);float p[2]={0,0},s[2]={10,10};PickupSweepEnv e=Env();filter_value=1;CHECK(Player_CollectAndScoreFields(0,&m,p,s,&e)==0);CHECK(m.pickups[0].state==1&&stop_count==0);filter_value=0;m.pickups[0].position[0]=100;CHECK(Player_CollectAndScoreFields(0,&m,p,s,&e)==0);d.type=3;m.pickups[0].position[0]=0;m.pickups[0].position[1]=-20;CHECK(Player_CollectAndScoreFields(0,&m,p,s,&e)==0);}
static void TestTypeThreeInterval(){PickupManager m;Reset(m);PickupDescriptor d;SetupPickup(m,d,3);float p[2]={0,5},s[2]={10,10};PickupSweepEnv e=Env();interval_value=0;CHECK(Player_CollectAndScoreFields(0,&m,p,s,&e)==0);CHECK(m.pickups[0].state==1&&m.pickups[0].collected==1);CHECK(retire_count==0);Reset(m);SetupPickup(m,d,3);interval_value=1;CHECK(Player_CollectAndScoreFields(0,&m,p,s,&e)==30);}
static void InitRegion(PickupCollisionRegion& r){r.flags=1;r.width=20;r.height=10;r.center[0]=0;r.center[1]=0;r.previous_frame=1;r.current_frame=1;r.interval=4;r.value=40;r.limit=80;}
static void TestRegions(){PickupManager m;Reset(m);InitRegion(m.regions[0]);float p[2]={12,0},s[2]={6,2};PickupSweepEnv e=Env();player_value=5;CHECK(Player_CollectAndScoreFields(0,&m,p,s,&e)==45);CHECK(m.regions[0].accumulated==40&&m.regions[0].value==40);CHECK(score==101);p[0]=0;CHECK(Player_CollectAndScoreFields(0,&m,p,s,&e)==45);CHECK(m.regions[0].value==0);m.regions[1]=m.regions[0];m.regions[1].value=20;m.regions[1].limit=100;m.regions[1].current_frame=4;m.regions[1].previous_frame=3;CHECK(Player_CollectAndScoreFields(0,&m,p,s,&e)==5);}
static void TestRotatedAndCircle(){PickupManager m;Reset(m);InitRegion(m.regions[0]);m.regions[0].angle=1.5707963268f;m.regions[0].width=20;m.regions[0].height=4;m.regions[0].value=11;m.regions[0].limit=99;float p[2]={0,8},s[2]={2,2};PickupSweepEnv e=Env();CHECK(Player_CollectAndScoreFields(0,&m,p,s,&e)==11);Reset(m);PickupCollisionRegion&r=m.regions[0];r.flags=3;r.radius=5;r.center[0]=3;r.center[1]=4;r.previous_frame=r.current_frame=0;r.interval=1;r.value=9;r.limit=9;p[0]=0;p[1]=0;CHECK(Player_CollectAndScoreFields(0,&m,p,s,&e)==9);CHECK(r.value==0);}
static void TestCap(){PickupManager m;Reset(m);float p[2]={0,0},s[2]={1,1};PickupSweepEnv e=Env();score=999999999;player_value=100;CHECK(Player_CollectAndScoreFields(0,&m,p,s,&e)==100);CHECK(score==999999999);}
int main(){TestEarly();TestOrdinaryPickup();TestFilterAndBounds();TestTypeThreeInterval();TestRegions();TestRotatedAndCircle();TestCap();if(fails)return 1;std::printf("recovery_batch28_test passed\n");}
